package tests

import (
	"errors"
	"sync"
	"testing"
	"time"

	"exercise/src/tickets"
)

// gatedInventory makes concurrent buyers overlap: Remaining waits until `peers`
// callers have read the count (or 30ms passes), so every buyer sees the same
// count before any of them takes seats.
type gatedInventory struct {
	tickets.Inventory
	mu      sync.Mutex
	peers   int
	arrived int
	open    chan struct{}
}

func newGated(inv tickets.Inventory, peers int) *gatedInventory {
	return &gatedInventory{Inventory: inv, peers: peers, open: make(chan struct{})}
}

func (g *gatedInventory) Remaining(event string) (int, error) {
	left, err := g.Inventory.Remaining(event)
	g.mu.Lock()
	g.arrived++
	if g.arrived == g.peers {
		close(g.open)
	}
	g.mu.Unlock()
	select {
	case <-g.open:
	case <-time.After(30 * time.Millisecond):
	}
	return left, err
}

func holdAll(b *tickets.BoxOffice, event string, buyers, each int) (ok int) {
	var wg sync.WaitGroup
	var mu sync.Mutex
	for i := 0; i < buyers; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if err := b.Hold(event, each); err == nil {
				mu.Lock()
				ok++
				mu.Unlock()
			}
		}()
	}
	wg.Wait()
	return ok
}

func TestHoldTakesSeats(t *testing.T) {
	inv := tickets.NewMemoryInventory(map[string]int{"hamlet": 10})
	b := tickets.NewBoxOffice(inv)
	if err := b.Hold("hamlet", 4); err != nil {
		t.Fatal(err)
	}
	left, _ := inv.Remaining("hamlet")
	if left != 6 || b.Held("hamlet") != 4 {
		t.Fatalf("remaining=%d held=%d, want 6 and 4", left, b.Held("hamlet"))
	}
}

func TestSoldOut(t *testing.T) {
	b := tickets.NewBoxOffice(tickets.NewMemoryInventory(map[string]int{"hamlet": 3}))
	if err := b.Hold("hamlet", 4); !errors.Is(err, tickets.ErrSoldOut) {
		t.Fatalf("got %v, want ErrSoldOut", err)
	}
	if b.Held("hamlet") != 0 {
		t.Fatalf("failed hold must not be recorded, held=%d", b.Held("hamlet"))
	}
}

func TestBadQuantityAndUnknownEvent(t *testing.T) {
	b := tickets.NewBoxOffice(tickets.NewMemoryInventory(map[string]int{"hamlet": 3}))
	if err := b.Hold("hamlet", 0); !errors.Is(err, tickets.ErrBadQuantity) {
		t.Fatalf("got %v, want ErrBadQuantity", err)
	}
	if err := b.Hold("macbeth", 1); !errors.Is(err, tickets.ErrUnknownEvent) {
		t.Fatalf("got %v, want ErrUnknownEvent", err)
	}
}

func TestTwoBuyersOneLastPair(t *testing.T) {
	inv := tickets.NewMemoryInventory(map[string]int{"hamlet": 2})
	b := tickets.NewBoxOffice(newGated(inv, 2))
	ok := holdAll(b, "hamlet", 2, 2)
	left, _ := inv.Remaining("hamlet")
	if ok != 1 || left != 0 {
		t.Fatalf("%d buyers got the last 2 seats and %d remain; want exactly 1 buyer and 0 left", ok, left)
	}
}

func TestManyBuyersNeverOversell(t *testing.T) {
	inv := tickets.NewMemoryInventory(map[string]int{"hamlet": 5})
	b := tickets.NewBoxOffice(newGated(inv, 12))
	ok := holdAll(b, "hamlet", 12, 1)
	left, _ := inv.Remaining("hamlet")
	if left < 0 || ok != 5 {
		t.Fatalf("12 buyers for 5 seats: %d succeeded, %d remaining (want 5 and 0)", ok, left)
	}
}

func TestHeldNeverExceedsCapacity(t *testing.T) {
	inv := tickets.NewMemoryInventory(map[string]int{"hamlet": 6})
	b := tickets.NewBoxOffice(newGated(inv, 4))
	holdAll(b, "hamlet", 4, 3)
	if b.Held("hamlet") > 6 {
		t.Fatalf("held %d seats of a 6-seat house", b.Held("hamlet"))
	}
}

func TestReport(t *testing.T) {
	capacity := map[string]int{"hamlet": 4, "othello": 2}
	inv := tickets.NewMemoryInventory(capacity)
	b := tickets.NewBoxOffice(newGated(inv, 3))
	holdAll(b, "hamlet", 3, 2)
	_ = b.Hold("othello", 1)
	out := tickets.Report(b, capacity)
	t.Log("\n" + out)
	if want := "hamlet: 4/4 held\nothello: 1/2 held\n"; out != want {
		t.Fatalf("report:\n%s\nwant:\n%s", out, want)
	}
}
